-- ============================================================================
-- NLE Seed Questions Part 2B: ETHICS (011), NUTRITION (012),
--   OPERATION ROOM NURSING (013), EMERGENCY & DISASTER (014)
-- 148 questions. Run after nle-seed-questions-part2a.sql and options-4/5.
-- ============================================================================

BEGIN;

INSERT INTO nle_question_bank (id, category_id, question_text, question_type, difficulty, explanation, is_high_yield, is_active, created_at, updated_at) VALUES
-- ETHICS & LEGAL (37 questions)
('b0000011-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000011', 'What is informed consent?', 'MC', 'MEDIUM', 'Informed consent is a legal and ethical process in which a patient voluntarily agrees to a procedure or treatment after being informed of the diagnosis, nature and purpose of treatment, risks, benefits, alternatives, and consequences of refusal.', true, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000002', 'a1000000-0000-0000-0000-000000000011', 'Which client cannot legally give informed consent?', 'MC', 'MEDIUM', 'Minors (under 18 in the Philippines), mentally incompetent persons, and unconscious patients cannot give informed consent. Consent is obtained from a parent, legal guardian, or court-appointed representative.', true, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000003', 'a1000000-0000-0000-0000-000000000011', 'What is the difference between assault and battery?', 'MC', 'MEDIUM', 'Assault is the threat or attempt to harm another without touching (creating reasonable fear). Battery is the actual unlawful touching or harmful contact without consent. Both are intentional torts.', false, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000004', 'a1000000-0000-0000-0000-000000000011', 'What constitutes negligence in nursing?', 'MC', 'MEDIUM', 'Negligence (tort) is failure to provide the standard of care that a reasonably prudent nurse would provide in similar circumstances, causing harm. It requires duty, breach of duty, causation, and damages (foreseeability).', true, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000005', 'a1000000-0000-0000-0000-000000000011', 'What is malpractice?', 'MC', 'MEDIUM', 'Malpractice is professional negligence by a licensed practitioner who fails to exercise the degree of skill and care expected of a competent professional, resulting in injury to the client.', true, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000011', 'What is the principle of beneficence?', 'MC', 'MEDIUM', 'Beneficence is the ethical duty to act for the benefit of the patient, promoting good and preventing harm. In nursing, it means providing care that maximizes benefits and minimizes risks for the client.', false, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000007', 'a1000000-0000-0000-0000-000000000011', 'Which ethical principle is violated when a nurse breaches patient confidentiality?', 'MC', 'MEDIUM', 'Confidentiality (and the related principle of privacy) is violated. Disclosure of patient information without authorization breaches the nurse-client relationship and can result in disciplinary action under the Nursing Act.', true, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000008', 'a1000000-0000-0000-0000-000000000011', 'What does the principle of autonomy guarantee to a patient?', 'MC', 'MEDIUM', 'Autonomy (self-determination) guarantees the right of a competent adult to make decisions about their own care, including the right to refuse treatment. Paternalism overrides this right for the supposed benefit of the patient.', true, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000009', 'a1000000-0000-0000-0000-000000000011', 'A competent patient refuses a blood transfusion. What should the nurse do?', 'MC', 'MEDIUM', 'A competent adult has the right to refuse treatment. The nurse must respect the refusal, inform the physician, document the refusal and teaching given, and ensure the patient understands the consequences.', true, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000010', 'a1000000-0000-0000-0000-000000000011', 'What is the statute of limitations?', 'MC', 'MEDIUM', 'The statute of limitations is the maximum time after an event within which legal action may be filed. It varies by jurisdiction and type of case; after it expires, a lawsuit cannot be brought.', false, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000011', 'a1000000-0000-0000-0000-000000000011', 'What is a living will (advance directive)?', 'MC', 'MEDIUM', 'A living will is a written advance directive stating a person wishes regarding life-sustaining treatment if they become terminally ill and unable to communicate. It takes effect when the patient cannot make decisions.', true, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000012', 'a1000000-0000-0000-0000-000000000011', 'Who serves as the legal proxy in a durable power of attorney for health care?', 'MC', 'MEDIUM', 'A healthcare proxy (agent) is designated by the patient to make medical decisions on their behalf if the patient becomes incapacitated. The choice must be documented and communicated to the healthcare team.', false, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000013', 'a1000000-0000-0000-0000-000000000011', 'What is the ethical principle of justice in healthcare?', 'MC', 'MEDIUM', 'Justice means fairness and equity in the distribution of resources and in treating like cases alike. It requires that care not be denied based on race, gender, socioeconomic status, or ability to pay.', false, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000014', 'a1000000-0000-0000-0000-000000000011', 'Which act of negligence involves giving the wrong medication?', 'MC', 'MEDIUM', 'A medication error (commission) such as giving the wrong drug, wrong dose, or wrong route is a form of negligence if it departs from the standard of care and causes harm. It must be reported and documented.', false, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000015', 'a1000000-0000-0000-0000-000000000011', 'What is abandonment in the nurse-client relationship?', 'MC', 'MEDIUM', 'Abandonment occurs when a nurse terminates care without proper notice or transfer of responsibility while the client still needs nursing care. It can result in loss of licensure and civil liability.', false, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000016', 'a1000000-0000-0000-0000-000000000011', 'What is defamation of character, and what are its forms?', 'MC', 'MEDIUM', 'Defamation is a false statement that harms a person reputation. Libel is written; slander is spoken. In nursing, documenting unprofessionally or gossiping about a patient can constitute defamation.', false, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000017', 'a1000000-0000-0000-0000-000000000011', 'What is the nurse role when a colleague is impaired by substance abuse?', 'MC', 'MEDIUM', 'The nurse must not conceal impairment; patient safety comes first. The nurse should remove the impaired colleague from patient care, notify the supervisor, and refer the colleague to the employee assistance or peer assistance program.', true, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000018', 'a1000000-0000-0000-0000-000000000011', 'What is the principle of nonmaleficence?', 'MC', 'MEDIUM', 'Nonmaleficence is the duty to do no harm (primum non nocere). It requires nurses to avoid causing unnecessary suffering, avoid risky procedures without benefit, and report unsafe conditions.', true, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000019', 'a1000000-0000-0000-0000-000000000011', 'Which scenario best describes a breach of confidentiality?', 'MC', 'MEDIUM', 'Discussing a patient condition in a public area such as an elevator, cafeteria, or social media constitutes a breach of confidentiality, even without naming the patient if they can be identified.', true, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000020', 'a1000000-0000-0000-0000-000000000011', 'What is informed refusal?', 'MC', 'MEDIUM', 'Informed refusal is the right of a client to decline treatment after being informed of the diagnosis, proposed treatment, risks, benefits, and alternatives. The refusal must be documented, and the client should sign a waiver.', false, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000021', 'a1000000-0000-0000-0000-000000000011', 'What is the responsibility of a nurse as an ethical advocate?', 'MC', 'MEDIUM', 'As advocate, the nurse protects client rights, ensures informed consent, communicates client preferences to the healthcare team, and speaks up when client welfare is threatened, even against institutional pressure.', false, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000022', 'a1000000-0000-0000-0000-000000000011', 'What is the doctrine of respondeat superior?', 'MC', 'MEDIUM', 'Respondeat superior (let the master answer) makes the employer legally liable for the negligent acts of employees committed within the scope of employment. The employer, not only the employee, can be sued.', true, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000023', 'a1000000-0000-0000-0000-000000000011', 'Which documentation practice is legally correct?', 'MC', 'MEDIUM', 'Correct documentation is timely, factual, objective, accurate, complete, and signed with name and title. Errors are corrected with a single line, initial and date; never use correction fluid or erase entries.', true, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000024', 'a1000000-0000-0000-0000-000000000011', 'What are the elements of a valid contract?', 'MC', 'MEDIUM', 'A valid contract requires: competent parties, mutual consent (offer and acceptance), lawful object/purpose, and consideration (something of value exchanged). All four must be present for enforceability.', false, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000025', 'a1000000-0000-0000-0000-000000000011', 'What is assault in the context of patient care?', 'MC', 'MEDIUM', 'Threatening a patient with an injection intended to frighten or coercing a patient through threats constitutes assault, even without touching. Threatening words or gestures that create fear are enough.', false, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000026', 'a1000000-0000-0000-0000-000000000011', 'A patient asks the nurse to keep a terminal diagnosis from the family. What is the nurse ethical obligation?', 'MC', 'HARD', 'The patient autonomy and right to privacy govern who receives information. Unless the patient authorizes disclosure, the nurse must respect confidentiality while ensuring the patient is encouraged to involve family or the healthcare team, and document the request.', true, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000027', 'a1000000-0000-0000-0000-000000000011', 'What is the process of ethical decision making for nurses?', 'MC', 'MEDIUM', 'Ethical decision making: assess the facts, identify the ethical problem, consider options using ethical principles (beneficence, autonomy, justice), consult codes and laws, choose the best action, implement, and evaluate outcomes.', false, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000028', 'a1000000-0000-0000-0000-000000000011', 'What is negligent omission?', 'MC', 'MEDIUM', 'Negligent omission (commission by neglect) is failing to act when there is a duty to act, such as failing to monitor a patient, not calling the physician for critical values, or omitting ordered care.', false, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000029', 'a1000000-0000-0000-0000-000000000011', 'What is the right of a patient to inspect their own medical record?', 'MC', 'MEDIUM', 'Patients have the right to inspect and obtain copies of their medical records. The facility may charge a reasonable fee for copies. Records remain the property of the health care provider/facility.', false, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000030', 'a1000000-0000-0000-0000-000000000011', 'What is the principle of veracity?', 'MC', 'MEDIUM', 'Veracity is the duty to tell the truth and be honest with clients. Deception, even well-intentioned, undermines trust and informed consent. Nurses must provide truthful, appropriate information at the patient level of understanding.', false, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000031', 'a1000000-0000-0000-0000-000000000011', 'Which action best protects the nurse from liability?', 'MC', 'MEDIUM', 'Following the standards of care, practicing within the legal scope of licensure, documenting accurately and promptly, obtaining informed consent, and communicating changes to the physician protect against liability.', true, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000032', 'a1000000-0000-0000-0000-000000000011', 'What is assault and battery in the case of an unwanted surgical procedure?', 'MC', 'MEDIUM', 'Performing a procedure beyond the scope of the consent given (e.g., removing an organ not consented to) is battery. Operating without valid consent is both assault and battery and is a criminal offense.', false, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000033', 'a1000000-0000-0000-0000-000000000011', 'When may patient confidentiality be broken?', 'MC', 'MEDIUM', 'Confidentiality may be broken when required by law (reportable diseases such as TB, HIV per statute, gunshot wounds, child/elder abuse), court order, or to prevent imminent harm to the patient or others (duty to warn).', true, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000034', 'a1000000-0000-0000-0000-000000000011', 'What is a quasi-contract in nursing?', 'MC', 'HARD', 'A quasi-contract is not a true contract but an obligation imposed by law to prevent unjust enrichment. In nursing, it may arise when care is provided in an emergency under implied consent (implied-in-fact contract).', false, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000035', 'a1000000-0000-0000-0000-000000000011', 'What is the ethical issue of futility in treatment?', 'MC', 'HARD', 'Treatment futility refers to interventions that cannot achieve the intended physiological goal. Ethically, there is no obligation to provide futile treatment; the focus shifts to comfort care and goals-of-care discussion with the family.', false, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000036', 'a1000000-0000-0000-0000-000000000011', 'How should a nurse handle a situation where a physician orders a treatment the nurse believes is harmful?', 'MC', 'MEDIUM', 'The nurse should seek clarification with the physician first. If the order is clearly erroneous and unsafe and persists, the nurse must refuse to carry it out and escalate to the supervisor, documenting the concern.', true, true, NOW(), NOW()),
('b0000011-0000-0000-0000-000000000037', 'a1000000-0000-0000-0000-000000000011', 'What is the ethical principle underlying end-of-life decisions such as DNR orders?', 'MC', 'MEDIUM', 'Autonomy (respecting the patient wishes expressed in advance directives) and beneficence/nonmaleficence (avoiding burdensome interventions) underlie DNR decisions. DNR means no cardiopulmonary resuscitation, not no treatment.', true, true, NOW(), NOW()),
-- NUTRITION & DIETETICS (37 questions)
('b0000012-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000012', 'How many kilocalories per gram do carbohydrates and proteins provide?', 'MC', 'EASY', 'Carbohydrates and proteins each provide 4 kcal per gram; fats provide 9 kcal per gram; and alcohol provides 7 kcal per gram. Carbohydrates are the body preferred and most efficient energy source.', true, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000002', 'a1000000-0000-0000-0000-000000000012', 'What is the recommended dietary allowance of protein for a normal adult?', 'MC', 'MEDIUM', 'The RDA for protein is 0.8 g/kg body weight per day for healthy adults (about 56 g for men, 46 g for women). Needs increase in pregnancy, lactation, growth, and recovery from illness or surgery.', false, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000003', 'a1000000-0000-0000-0000-000000000012', 'Which vitamin deficiency causes scurvy?', 'MC', 'EASY', 'Vitamin C (ascorbic acid) deficiency causes scurvy, characterized by bleeding gums, poor wound healing, petechiae, corkscrew hairs, and joint pain. Citrus fruits, tomatoes, and green leafy vegetables are rich sources.', true, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000004', 'a1000000-0000-0000-0000-000000000012', 'Which vitamin deficiency causes rickets in children and osteomalacia in adults?', 'MC', 'MEDIUM', 'Vitamin D deficiency impairs calcium absorption, causing rickets (bowed legs, widened epiphyses) in children and osteomalacia (soft bones) in adults. Vitamin D is obtained from sunlight exposure, fortified milk, and fatty fish.', true, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000005', 'a1000000-0000-0000-0000-000000000012', 'Which vitamin deficiency causes beriberi?', 'MC', 'MEDIUM', 'Thiamine (vitamin B1) deficiency causes beriberi: wet beriberi presents with heart failure and edema; dry beriberi with peripheral neuropathy and muscle wasting. It is common in polished-rice diets.', true, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000012', 'What disease is caused by niacin (vitamin B3) deficiency?', 'MC', 'MEDIUM', 'Niacin deficiency causes pellagra, classically described as the four Ds: dermatitis, diarrhea, dementia, and death if untreated. It is common in populations dependent on corn (maize) without niacin supplementation.', false, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000007', 'a1000000-0000-0000-0000-000000000012', 'Which mineral is essential for hemoglobin formation?', 'MC', 'EASY', 'Iron is a component of hemoglobin and myoglobin. Deficiency causes iron-deficiency anemia with fatigue, pallor, pica, koilonychia (spoon nails), and glossitis. Heme iron from meat is better absorbed than non-heme iron.', true, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000008', 'a1000000-0000-0000-0000-000000000012', 'What does vitamin K do in the body?', 'MC', 'MEDIUM', 'Vitamin K is essential for the synthesis of clotting factors II, VII, IX, and X in the liver. Deficiency causes prolonged PT and bleeding. It is produced by intestinal flora and found in green leafy vegetables.', true, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000009', 'a1000000-0000-0000-0000-000000000012', 'Which vitamin is essential for red blood cell maturation, and what deficiency causes megaloblastic anemia?', 'MC', 'MEDIUM', 'Vitamin B12 (cobalamin) and folate are essential for RBC maturation and DNA synthesis. Deficiency causes megaloblastic (macrocytic) anemia with glossitis and neurologic changes; B12 deficiency also causes subacute combined degeneration of the spinal cord.', true, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000010', 'a1000000-0000-0000-0000-000000000012', 'What is the normal caloric distribution of carbohydrates in a balanced diet?', 'MC', 'MEDIUM', 'A balanced diet derives about 55-60% of calories from carbohydrates, 20-30% from fats, and 10-15% from proteins (Acceptable Macronutrient Distribution Ranges). Carbohydrates should be complex, high-fiber sources.', false, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000011', 'a1000000-0000-0000-0000-000000000012', 'What is the recommended daily water intake for a healthy adult?', 'MC', 'MEDIUM', 'A common guideline is about 8 glasses (approximately 1.5-2 liters) daily, but individual needs vary with body weight, activity, and climate. A practical estimate is 30-35 mL per kg body weight per day.', false, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000012', 'a1000000-0000-0000-0000-000000000012', 'What dietary modification is recommended for a patient with hypertension?', 'MC', 'MEDIUM', 'A low-sodium diet (DASH diet) is recommended: limit sodium to less than 2,300 mg/day (ideally 1,500 mg), increase fruits, vegetables, whole grains, and potassium-rich foods, and limit alcohol.', true, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000013', 'a1000000-0000-0000-0000-000000000012', 'Which diet is appropriate for a patient with chronic kidney disease (stage 5, on dialysis)?', 'MC', 'HARD', 'A renal diet is low in protein (or restricted to high biological value protein before dialysis), low in potassium, low in phosphorus, and fluid-restricted after dialysis is initiated. Sodium is also restricted.', true, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000014', 'a1000000-0000-0000-0000-000000000012', 'What is the Glycemic Index (GI)?', 'MC', 'MEDIUM', 'The glycemic index ranks carbohydrate foods by how quickly they raise blood glucose compared with a reference food. Low-GI foods (whole grains, most fruits) produce slower, steadier glucose rises and are preferred in diabetes management.', false, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000015', 'a1000000-0000-0000-0000-000000000012', 'What is the dietary management for diabetes mellitus?', 'MC', 'MEDIUM', 'Diabetes management includes consistent carbohydrate intake at scheduled meals, high fiber, low saturated fat and sodium, portion control, and pairing carbohydrates with protein/fat to blunt glucose spikes. Individualized medical nutrition therapy is standard.', true, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000016', 'a1000000-0000-0000-0000-000000000012', 'What does BMI (body mass index) measure?', 'MC', 'MEDIUM', 'BMI is weight in kilograms divided by height in meters squared (kg/m2). Categories: underweight <18.5, normal 18.5-24.9, overweight 25-29.9, obese 30 and above. It estimates weight status but not body composition directly.', true, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000017', 'a1000000-0000-0000-0000-000000000012', 'Which nutrient is the body preferred source of energy?', 'MC', 'EASY', 'Carbohydrates are the preferred and most efficient energy source for the brain and muscles. The brain specifically relies on glucose; in its absence, the body breaks down fat and protein (ketosis, gluconeogenesis).', true, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000018', 'a1000000-0000-0000-0000-000000000012', 'What is the function of dietary fiber?', 'MC', 'MEDIUM', 'Fiber adds bulk, promotes peristalsis, prevents constipation and diverticulosis, binds cholesterol and bile acids (lowering LDL), slows glucose absorption, and provides satiety. Water intake must increase with high fiber.', false, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000019', 'a1000000-0000-0000-0000-000000000012', 'What are the signs of protein-calorie malnutrition (kwashiorkor vs marasmus)?', 'MC', 'MEDIUM', 'Kwashiorkor: adequate calories but protein deficiency, with edema, fatty liver, skin changes, and apathy. Marasmus: total calorie and protein deficiency with severe wasting, loss of muscle and fat, and an alert, hungry appearance.', true, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000020', 'a1000000-0000-0000-0000-000000000012', 'Which vitamin is a fat-soluble vitamin?', 'MC', 'MEDIUM', 'Fat-soluble vitamins are A, D, E, and K, which are absorbed with dietary fat and stored in the liver and adipose tissue. Water-soluble vitamins are the B complex and vitamin C, which are excreted when in excess.', true, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000021', 'a1000000-0000-0000-0000-000000000012', 'What is the therapeutic use of a low-cholesterol, low-saturated-fat diet?', 'MC', 'MEDIUM', 'A cardiac diet (therapeutic diet) limits saturated fats, trans fats, and cholesterol to reduce serum LDL and slow atherosclerosis. Sources to avoid include organ meats, egg yolks, fried foods, and full-fat dairy.', false, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000022', 'a1000000-0000-0000-0000-000000000012', 'What is a clear liquid diet, and when is it prescribed?', 'MC', 'MEDIUM', 'A clear liquid diet provides fluids and some electrolytes with minimal residue (broth, gelatin, clear juices, tea, black coffee). It is prescribed postoperative when the GI tract must resume function gradually, before advanced to full liquids.', false, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000023', 'a1000000-0000-0000-0000-000000000012', 'Which foods should be avoided on a low-tyramine diet (patient on MAOIs)?', 'MC', 'MEDIUM', 'Avoid aged cheeses, cured/fermented meats (salami, sausages), pickled foods, soy sauce, sauerkraut, draft beer, red wine, and overripe/fermented foods. Tyramine plus MAO inhibition can cause hypertensive crisis.', true, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000024', 'a1000000-0000-0000-0000-000000000012', 'What is the recommended feeding position to prevent aspiration?', 'MC', 'MEDIUM', 'The client should sit upright (high Fowler, at least 60-90 degrees) during and for 30-60 minutes after meals. This uses gravity to reduce reflux and aspiration risk, especially in elderly, stroke, or dysphagic patients.', true, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000025', 'a1000000-0000-0000-0000-000000000012', 'What is the correct order of advancing a diet postoperatively?', 'MC', 'MEDIUM', 'Diet progression: NPO → clear liquids → full liquids → soft/low residue → regular, as tolerated. Advancement requires return of bowel sounds, passage of flatus, absence of nausea/vomiting, and physician order.', false, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000026', 'a1000000-0000-0000-0000-000000000012', 'Which electrolyte is tightly regulated by the kidneys and important in nerve and muscle function?', 'MC', 'MEDIUM', 'Potassium is the major intracellular cation critical for cardiac, nerve, and muscle function. Normal serum level is 3.5-5.0 mEq/L. Both hypokalemia and hyperkalemia can cause fatal cardiac dysrhythmias.', true, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000027', 'a1000000-0000-0000-0000-000000000012', 'What is the nursing intervention for a patient with dysphagia?', 'MC', 'MEDIUM', 'Feed the patient sitting upright at 90 degrees, place food on the unaffected (stronger) side, offer small amounts, have the patient chew and swallow each bolus before more, check the mouth afterward, and thicken liquids as prescribed.', true, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000028', 'a1000000-0000-0000-0000-000000000012', 'What does the term basal metabolic rate (BMR) mean?', 'MC', 'MEDIUM', 'BMR is the energy expended at complete rest in a fasting state 12-14 hours after the last meal, in a thermoneutral environment. It is measured by oxygen consumption and influenced by age, sex, hormones, and body surface area.', false, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000029', 'a1000000-0000-0000-0000-000000000012', 'Which trace mineral is required for thyroid hormone synthesis?', 'MC', 'MEDIUM', 'Iodine is required for the synthesis of T3 and T4 by the thyroid gland. Deficiency causes goiter and cretinism in newborns; iodized salt programs prevent iodine deficiency disorders.', false, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000030', 'a1000000-0000-0000-0000-000000000012', 'What is the effect of calcium deficiency in adults?', 'MC', 'MEDIUM', 'Calcium deficiency (hypocalcemia) causes tetany, muscle cramps, hyperactive reflexes, Chvostek and Trousseau signs, and with chronic deficiency, osteoporosis. Vitamin D, magnesium, and phosphorus influence calcium balance.', false, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000031', 'a1000000-0000-0000-0000-000000000012', 'What is the calorie requirement during pregnancy?', 'MC', 'MEDIUM', 'Pregnancy requires an additional approximately 340 kcal/day in the second trimester and 450 kcal/day in the third trimester (about 2,500 kcal/day total for many women), with emphasis on protein, folate, iron, and calcium.', false, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000032', 'a1000000-0000-0000-0000-000000000012', 'Which diet is prescribed for a patient with peptic ulcer disease?', 'MC', 'MEDIUM', 'Formerly bland and frequent small feedings (to neutralize acid), current management emphasizes H. pylori eradication, avoidance of NSAIDs, alcohol, caffeine, and smoking, and small frequent bland meals as tolerated.', false, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000033', 'a1000000-0000-0000-0000-000000000012', 'What is the purpose of total parenteral nutrition (TPN)?', 'MC', 'MEDIUM', 'TPN provides complete nutrition (dextrose, amino acids, lipids, vitamins, minerals) intravenously when the GI tract cannot be used or cannot meet needs. Complications include hyperglycemia, infection, and refeeding syndrome.', true, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000034', 'a1000000-0000-0000-0000-000000000012', 'What are the components of a complete food group according to MyPlate/Food Pyramid?', 'MC', 'EASY', 'The major groups are grains, vegetables, fruits, protein foods, and dairy (with oils and discretionary calories). A balanced plate is half fruits and vegetables, one quarter grains, and one quarter protein.', false, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000035', 'a1000000-0000-0000-0000-000000000012', 'What is the primary role of carbohydrates in the body?', 'MC', 'EASY', 'Carbohydrates provide immediate energy for cellular functions, the brain, and the nervous system; spare protein for growth and repair; and aid in fat metabolism. Excess carbohydrates are stored as glycogen and fat.', false, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000036', 'a1000000-0000-0000-0000-000000000012', 'Which vitamin is produced by bacteria in the intestine and is needed for calcium absorption?', 'MC', 'MEDIUM', 'Vitamin D works with calcium: it promotes calcium absorption in the gut and mineralization of bone. Sources include sunlight (7-dehydrocholesterol converted in skin), fortified milk, egg yolk, and fatty fish.', false, true, NOW(), NOW()),
('b0000012-0000-0000-0000-000000000037', 'a1000000-0000-0000-0000-000000000012', 'What nursing consideration applies when weighing a patient on a weight-reduction diet?', 'MC', 'MEDIUM', 'Weigh the patient at the same time of day, in the same amount of clothing, on the same scale, preferably before breakfast after voiding, to ensure accurate and comparable weight recordings for tracking progress.', false, true, NOW(), NOW()),
-- OPERATION ROOM NURSING (37 questions)
('b0000013-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000013', 'What is the correct surgical scrub duration for a first scrub?', 'MC', 'MEDIUM', 'A first surgical scrub lasts 3-5 minutes (commonly 5 minutes including nail beds and up to the elbows), with hands and arms held above elbow level so water drains from the least clean area (fingertips) to the most clean (elbows).', true, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000002', 'a1000000-0000-0000-0000-000000000013', 'In the surgical positioning, what does lithotomy position mean?', 'MC', 'MEDIUM', 'Lithotomy position: the client lies supine with legs elevated and supported in stirrups, hips flexed and abducted. Used for gynecologic, urologic, and rectal procedures. Risks include peroneal nerve injury and compartment syndrome.', true, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000003', 'a1000000-0000-0000-0000-000000000013', 'What is the purpose of the surgical safety checklist?', 'MC', 'MEDIUM', 'The WHO Surgical Safety Checklist verifies the correct patient, correct site (sign-marked), correct procedure, consent, allergies, airway risk, antibiotic prophylaxis timing, and counts at sign-in, time-out, and sign-out phases.', true, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000004', 'a1000000-0000-0000-0000-000000000013', 'What is the correct count of surgical sponges, needles, and instruments?', 'MC', 'MEDIUM', 'Counts are performed and documented before surgery begins (initial count), whenever a new pack or additional items are added, before closing a body cavity, and at skin closure. All counts must match; discrepancies require X-ray before closure.', true, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000005', 'a1000000-0000-0000-0000-000000000013', 'What type of drape is considered impermeable and provides a sterile barrier?', 'MC', 'MEDIUM', 'Impermeable (fluid-resistant) drapes provide a sterile barrier against strike-through contamination. Drapes must be applied with the moisture-resistant side toward the surgical field, and the fenestrated area exposes only the operative site.', false, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000013', 'Which anesthesia is used for minor superficial procedures?', 'MC', 'MEDIUM', 'Local anesthesia (infiltration, topical) numbs a small, specific area and is used for superficial minor procedures (e.g., abscess drainage, suturing). The client remains fully conscious with an intact gag reflex.', false, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000007', 'a1000000-0000-0000-0000-000000000013', 'What is the priority positioning concern in the prone position?', 'MC', 'MEDIUM', 'In prone positioning, airway access is limited and venous return can be compromised by pressure on the abdomen and vena cava. Padding pressure points, avoiding abdominal compression, and protecting the eyes and brachial plexus are essential.', false, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000008', 'a1000000-0000-0000-0000-000000000013', 'What is the purpose of a surgical drain such as a Penrose drain?', 'MC', 'MEDIUM', 'Drains remove blood, bile, pus, or other fluids from a surgical site to prevent accumulation, distension, and infection. A Penrose drain works by gravity and capillary action through an open system into a collected dressing.', false, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000009', 'a1000000-0000-0000-0000-000000000013', 'What is electrocautery, and what is its nursing implication?', 'MC', 'MEDIUM', 'Electrosurgical units (Bovie) use high-frequency electrical current to cut or coagulate tissue. Risks include burns from grounding pad sites and fires. Safety: no flammable preps, keep O2 away, and ensure intact grounding pad contact with dry skin.', true, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000010', 'a1000000-0000-0000-0000-000000000013', 'What is the purpose of a time-out in the operating room?', 'MC', 'MEDIUM', 'The time-out is a pause immediately before incision when the entire surgical team verifies the correct patient, correct site (marked), correct procedure, and consent. No procedure proceeds until every member agrees.', true, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000011', 'a1000000-0000-0000-0000-000000000013', 'Which surgical instrument is used to clamp blood vessels?', 'MC', 'EASY', 'Hemostats (arterial forceps) clamp bleeding vessels to control hemorrhage. The nurse anticipates their use and may be asked to apply additional clamps or ligatures; all instruments must be counted.', false, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000012', 'a1000000-0000-0000-0000-000000000013', 'What are the stages of wound healing?', 'MC', 'MEDIUM', 'Wound healing stages: (1) hemostasis (clotting), (2) inflammation (vasodilation, phagocytosis), (3) proliferation (granulation tissue, collagen, angiogenesis), and (4) remodeling/maturation (scar strengthening, up to 1-2 years).', true, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000013', 'a1000000-0000-0000-0000-000000000013', 'What is the difference between primary, secondary, and tertiary intention healing?', 'MC', 'MEDIUM', 'Primary: clean surgical wound closed with sutures (least scar, least drainage). Secondary: wound left open to heal by granulation (large, infected wounds; most drainage). Tertiary: delayed closure after inflammation/infection control.', true, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000014', 'a1000000-0000-0000-0000-000000000013', 'What is the correct order for setting up a sterile field?', 'MC', 'MEDIUM', 'Open supplies are placed on the field from back to front, opening flaps away from the body so the outside (unsterile) surface never crosses the sterile field. The field is arranged within arm reach and below shoulder level.', false, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000015', 'a1000000-0000-0000-0000-000000000013', 'Which member of the surgical team is considered sterile?', 'MC', 'MEDIUM', 'The scrubbed nurse (and the surgeon) who have completed a surgical scrub and are gowned and gloved are considered sterile. The circulator is unsterile, as are anesthesiologists, visitors, and anyone whose gown becomes contaminated.', true, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000016', 'a1000000-0000-0000-0000-000000000013', 'What is the highest level of surgical asepsis?', 'MC', 'MEDIUM', 'Sterilization eliminates ALL forms of microbial life, including spores, and represents the highest level of asepsis. Antiseptics and disinfection reduce microorganisms but do not destroy spores.', true, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000017', 'a1000000-0000-0000-0000-000000000013', 'What is the priority assessment in the postanesthesia care unit (PACU)?', 'MC', 'MEDIUM', 'Airway patency and adequate ventilation are the priority. The nurse assesses ABCs: airway (head-tilt/chin-lift, suction), breathing (rate, depth, SpO2), and circulation (pulse, BP), along with level of consciousness.', true, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000018', 'a1000000-0000-0000-0000-000000000013', 'What is the most common early complication after general anesthesia?', 'MC', 'MEDIUM', 'Airway obstruction (from the tongue falling back, secretions, or laryngospasm) and nausea/vomiting are common early complications. Patients must be positioned laterally (recovery position) to prevent aspiration.', true, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000019', 'a1000000-0000-0000-0000-000000000013', 'Which complication is a client at greatest risk for after prolonged surgery in lithotomy position?', 'MC', 'MEDIUM', 'Prolonged lithotomy position risks peroneal nerve injury (foot drop), compartment syndrome of the lower legs, and lower back strain. The nurse assesses pedal pulses, sensation, movement, and pain disproportionate to procedure.', true, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000020', 'a1000000-0000-0000-0000-000000000013', 'What is hypothermia in the surgical client, and how is it prevented?', 'MC', 'MEDIUM', 'Surgical hypothermia (core temperature below 36 C) results from anesthesia-induced thermoregulatory loss and exposure. Prevention: warm IV fluids, forced-air warming blankets, warm room temperature, and covering exposed areas.', false, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000021', 'a1000000-0000-0000-0000-000000000013', 'What is the nursing intervention for a client with a surgical incision using purse-string or interrupted sutures?', 'MC', 'MEDIUM', 'Assess the incision for redness, swelling, dehiscence, and drainage; keep clean and dry per order; support the incision with a splint (abdominal binder or hands) during coughing; and monitor vital signs for infection.', false, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000022', 'a1000000-0000-0000-0000-000000000013', 'What is dehiscence and evisceration?', 'MC', 'MEDIUM', 'Dehiscence is the separation of wound layers. Evisceration is the protrusion of internal organs through the opened wound — a surgical emergency. Nursing: cover with sterile saline-moistened gown, keep client flexed with knees bent, and notify the surgeon immediately.', true, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000023', 'a1000000-0000-0000-0000-000000000013', 'What is the correct method for donning sterile gloves without contaminating them?', 'MC', 'MEDIUM', 'Using the open gloving method: the dominant hand picks up the inside surface (cuff, skin side) of the first glove, then the gloved hand slides fingers under the cuff (outside surface) to don the second glove. Never touch the outside.', true, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000024', 'a1000000-0000-0000-0000-000000000013', 'What is a surgical site infection (SSI), and what is a major nursing prevention measure?', 'MC', 'MEDIUM', 'SSI is an infection occurring at or near the incision within 30 days (or 1 year with implant). Prevention: proper skin preparation, sterile technique, normothermia, glycemic control, and timely preoperative antibiotic prophylaxis (within 60 minutes of incision).', true, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000025', 'a1000000-0000-0000-0000-000000000013', 'Which patient position places the greatest risk for brachial plexus stretch injury?', 'MC', 'MEDIUM', 'The Trendelenburg (head-down) position with arm boards and extreme abduction, lithotomy with adducted arms, and lateral position can stretch the brachial plexus. Arms should be abducted no more than 90 degrees on arm boards.', false, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000026', 'a1000000-0000-0000-0000-000000000013', 'What is the priority position after tonsillectomy to prevent aspiration of blood?', 'MC', 'MEDIUM', 'After tonsillectomy the client is positioned side-lying (lateral or prone with head tilted) so blood and secretions drain from the mouth rather than being swallowed or aspirated. The client is observed for bleeding (frequent swallowing, bright red secretions).', true, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000027', 'a1000000-0000-0000-0000-000000000013', 'What does the abbreviation TURP mean?', 'MC', 'EASY', 'TURP is transurethral resection of the prostate, performed through the urethra for benign prostatic hyperplasia. Postoperative irrigation (continuous bladder irrigation) prevents clot obstruction of the catheter.', false, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000028', 'a1000000-0000-0000-0000-000000000013', 'What is the purpose of a Jackson-Pratt (JP) drain?', 'MC', 'MEDIUM', 'A JP drain is a closed suction drain that removes fluid from the surgical site using bulb suction. The nurse must empty and measure output, keep the bulb compressed for suction, assess for kinks, and monitor for infection or hemorrhage.', false, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000029', 'a1000000-0000-0000-0000-000000000013', 'Which client is at highest risk for malignant hyperthermia?', 'MC', 'MEDIUM', 'Malignant hyperthermia is a life-threatening genetic reaction to volatile anesthetics (succinylcholine). Signs: rapidly rising temperature, rigidity, tachycardia, hypercapnia. Treatment: dantrolene sodium, active cooling, and ICU transfer.', true, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000030', 'a1000000-0000-0000-0000-000000000013', 'What is deep vein thrombosis (DVT) prophylaxis after surgery?', 'MC', 'MEDIUM', 'Prophylaxis includes early ambulation, sequential compression devices, anti-embolism (TED) stockings, adequate hydration, and anticoagulants when ordered. The nurse assesses for calf pain, swelling, warmth, and Homans sign.', true, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000031', 'a1000000-0000-0000-0000-000000000013', 'What is the appropriate handling of a soiled instrument tray during a procedure?', 'MC', 'MEDIUM', 'Contaminated instruments are kept on the sterile field until the end, then placed in a designated biohazard container for decontamination and sterilization. Contaminated items never re-enter the sterile field and require immediate re-gloving after handling.', false, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000032', 'a1000000-0000-0000-0000-000000000013', 'What happens if a sterile item touches an unsterile object?', 'MC', 'EASY', 'The sterile item is considered contaminated and must be replaced. Contamination can occur from a break in technique, contact with unsterile surfaces, moisture strike-through, or exceeding the expiration or sterilization date.', true, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000033', 'a1000000-0000-0000-0000-000000000013', 'What is the shortest safe distance for a sterile field from the edge of the table?', 'MC', 'MEDIUM', 'A sterile field is considered sterile only within the top surface of the table, at least 1 inch (2.54 cm) from the edge. Areas beyond that edge, the table legs, and the floor are considered unsterile.', false, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000034', 'a1000000-0000-0000-0000-000000000013', 'What is preoperative teaching aimed at achieving?', 'MC', 'EASY', 'Preoperative teaching reduces anxiety and prepares the client for the operative experience: expected sensations, deep breathing and incentive spirometry, coughing, leg exercises, pain management, and early ambulation to prevent complications.', false, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000035', 'a1000000-0000-0000-0000-000000000013', 'Which laboratory value is most important to check before surgery involving bleeding risk?', 'MC', 'MEDIUM', 'Coagulation studies (PT/INR, aPTT) and hemoglobin/hematocrit are critical before surgery. An INR above therapeutic range or anemia increases bleeding and transfusion risk; the surgeon may delay the procedure accordingly.', false, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000036', 'a1000000-0000-0000-0000-000000000013', 'What is the nursing responsibility regarding the surgical specimen?', 'MC', 'MEDIUM', 'The nurse verifies the label with two identifiers, ensures the specimen is properly identified with the correct site and procedure, uses the correct preservative (e.g., formalin), completes requisitions, and sends it promptly to the laboratory with the pathologist notification.', false, true, NOW(), NOW()),
('b0000013-0000-0000-0000-000000000037', 'a1000000-0000-0000-0000-000000000013', 'What is the recovery position used for a client emerging from anesthesia?', 'MC', 'MEDIUM', 'The client is placed in the lateral (recovery/Sims) position with the head of bed slightly elevated. This maintains a patent airway and allows drainage of secretions, reducing aspiration risk while the gag reflex returns.', true, true, NOW(), NOW()),
-- EMERGENCY & DISASTER NURSING (37 questions)
('b0000014-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000014', 'What are the priorities of emergency care using the ABCDE approach?', 'MC', 'MEDIUM', 'ABCDE: Airway (with cervical spine protection), Breathing, Circulation (hemorrhage control, IV access), Disability (neurologic status/GCS), and Exposure (full examination while preventing hypothermia). Reassess after each intervention.', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000002', 'a1000000-0000-0000-0000-000000000014', 'What is the correct compression-to-ventilation ratio for adult CPR?', 'MC', 'EASY', 'For single-rescuer adult CPR the ratio is 30 compressions to 2 breaths. Compressions are at a rate of 100-120 per minute and a depth of at least 2 inches (5 cm) but not more than 2.4 inches (6 cm).', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000003', 'a1000000-0000-0000-0000-000000000014', 'What is the recommended depth of chest compressions for an infant?', 'MC', 'MEDIUM', 'Infant compressions are at least one third of the anteroposterior chest diameter: about 1.5 inches (4 cm) for infants and 2 inches (5 cm) for children. Compression-to-ventilation is 30:2 (single rescuer) or 15:2 (two rescuers).', false, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000004', 'a1000000-0000-0000-0000-000000000014', 'In triage, how is the Immediate (Red) category defined in START triage?', 'MC', 'MEDIUM', 'Immediate (Red) casualties have life-threatening but survivable injuries requiring rapid intervention: respiratory rate over 30, absent radial pulse (capillary refill over 2 seconds), or inability to follow commands. They receive care first.', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000005', 'a1000000-0000-0000-0000-000000000014', 'What does the Disaster Probability Matrix evaluate?', 'MC', 'MEDIUM', 'The probability/impact matrix evaluates the likelihood of a hazard occurring against its potential impact (severity of consequences) to prioritize risk, allocate resources, and guide mitigation and preparedness planning.', false, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000014', 'Which phase of disaster management involves ongoing activities to reduce or eliminate long-term risk?', 'MC', 'MEDIUM', 'Mitigation is ongoing (before disaster) activity that reduces or eliminates long-term risk: building codes, land-use planning, dikes, education, and vulnerability assessment. Preparedness builds capacity; response acts during the event.', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000007', 'a1000000-0000-0000-0000-000000000014', 'What is the purpose of the Incident Command System (ICS)?', 'MC', 'MEDIUM', 'ICS provides a standardized, scalable organizational structure for incident management with clear chain of command, unity of command, and manageable span of control. It enables multi-agency coordination during emergencies and disasters.', false, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000008', 'a1000000-0000-0000-0000-000000000014', 'What are the four phases of emergency/disaster management?', 'MC', 'MEDIUM', 'The four phases are Mitigation (prevention/reduction), Preparedness (planning/training/exercises), Response (immediate actions during the event), and Recovery (restoration of normalcy). The cycle is continuous.', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000009', 'a1000000-0000-0000-0000-000000000014', 'What is the immediate action for a client with severe external hemorrhage?', 'MC', 'MEDIUM', 'Apply firm, direct pressure over the wound with a sterile dressing. If bleeding continues, apply a tourniquet proximal to the wound and note the time of application. Elevate the limb if no fracture is suspected and maintain pressure.', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000010', 'a1000000-0000-0000-0000-000000000014', 'How is the Glasgow Coma Scale (GCS) scored?', 'MC', 'MEDIUM', 'GCS = Eye (1-4) + Verbal (1-5) + Motor (1-6), total 3-15. A score of 13-15 is mild, 9-12 moderate, and 8 or less severe (indicates coma and need for airway protection). Best possible score is 15.', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000011', 'a1000000-0000-0000-0000-000000000014', 'What is the first action when encountering an accident scene?', 'MC', 'MEDIUM', 'Assess scene safety first — check for traffic, fire, electrical, chemical, or structural hazards before approaching. Do not become a second victim. Then check the victim for responsiveness and call for help (activate emergency response).', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000012', 'a1000000-0000-0000-0000-000000000014', 'What are the priority nursing interventions for a client in shock?', 'MC', 'MEDIUM', 'Shock priorities: ensure patent airway and oxygenation, control hemorrhage, establish two large-bore IV lines and initiate fluid resuscitation as ordered, position (supine with legs elevated unless contraindicated), monitor vital signs and urine output, and keep warm.', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000013', 'a1000000-0000-0000-0000-000000000014', 'What is the sign of hypovolemic shock in the early (compensated) stage?', 'MC', 'MEDIUM', 'Early hypovolemic shock: tachycardia (the earliest sign), narrowed pulse pressure, tachypnea, anxiety, and cool/clammy skin as compensation begins. Blood pressure may remain normal until significant volume (up to 30%) is lost.', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000014', 'a1000000-0000-0000-0000-000000000014', 'Which type of shock is characterized by warm, flushed skin?', 'MC', 'MEDIUM', 'Neurogenic and anaphylactic (distributive) shocks present with warm, flushed, vasodilated skin. Hypovolemic, cardiogenic, and obstructive shocks present with cool, pale, clammy skin. Differentiating these findings guides therapy.', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000015', 'a1000000-0000-0000-0000-000000000014', 'What is the priority intervention for anaphylactic shock?', 'MC', 'MEDIUM', 'Anaphylaxis treatment priority: IM epinephrine (1:1000, 0.3-0.5 mg adult) into the anterolateral thigh, repeat every 5-15 minutes as needed. Then high-flow oxygen, IV fluid, remove the trigger, and monitor for biphasic reaction.', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000016', 'a1000000-0000-0000-0000-000000000014', 'What is the treatment of choice for ventricular fibrillation (VF) on the cardiac monitor?', 'MC', 'MEDIUM', 'VF is pulseless and is treated with defibrillation (unsynchronized shock) as soon as a defibrillator is available, with CPR and epinephrine before/after shocks. Survival decreases about 7-10% for each minute without defibrillation.', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000017', 'a1000000-0000-0000-0000-000000000014', 'How do you distinguish ventricular tachycardia with a pulse from with no pulse?', 'MC', 'MEDIUM', 'Ventricular tachycardia with a pulse: synchronized cardioversion (or amiodarone if unstable). V-fib and pulseless V-tach: unsynchronized defibrillation plus high-quality CPR. Always check a pulse — never treat from the monitor alone without clinical assessment.', false, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000018', 'a1000000-0000-0000-0000-000000000014', 'What are the signs of a tension pneumothorax?', 'MC', 'MEDIUM', 'Tension pneumothorax: severe dyspnea, absent breath sounds on the affected side, tracheal deviation away from the affected side, hypotension, jugular vein distention, and cyanosis. It is a clinical emergency requiring immediate needle decompression.', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000019', 'a1000000-0000-0000-0000-000000000014', 'What is the immediate management of a tension pneumothorax?', 'MC', 'MEDIUM', 'Immediate needle decompression: insert a large-bore needle into the second intercostal space midclavicular line on the affected side, converting tension pneumothorax to simple pneumothorax, followed by chest tube insertion.', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000020', 'a1000000-0000-0000-0000-000000000014', 'What are the manifestations of heat stroke?', 'MC', 'MEDIUM', 'Heat stroke: core temperature above 40 C (104 F), hot/dry skin with ANHIDROSIS (absence of sweating), altered mental status/confusion/seizures, tachycardia, and multiorgan risk. It is a life-threatening emergency requiring active cooling.', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000021', 'a1000000-0000-0000-0000-000000000014', 'What is the nursing intervention for heat stroke?', 'MC', 'MEDIUM', 'Active cooling: remove excess clothing, apply cool water with fanning or ice packs to neck, axillae, and groin, provide cool IV fluids, monitor core temperature and stop cooling near 38.5 C, and support airway and seizures precautions. Call for emergency transport.', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000022', 'a1000000-0000-0000-0000-000000000014', 'What are the manifestations of hypothermia?', 'MC', 'MEDIUM', 'Hypothermia: core temperature below 35 C, progressive shivering (early) then cessation of shivering (severe), confusion, slurred speech, bradycardia, hypoventilation, and cold pale skin. Paradoxical undressing may occur in severe stages.', false, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000023', 'a1000000-0000-0000-0000-000000000014', 'What is the correct rewarming method for severe hypothermia?', 'MC', 'MEDIUM', 'Severe hypothermia requires active internal rewarming: warm humidified oxygen, warmed IV fluids (40-42 C), and peritoneal lavage or cardiopulmonary bypass. Handle the client gently (avoid rough movement that can trigger ventricular fibrillation) and remove wet clothing.', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000024', 'a1000000-0000-0000-0000-000000000014', 'What is the treatment priority for a client with an open (sucking) chest wound?', 'MC', 'MEDIUM', 'Apply an occlusive dressing taped on three sides (allowing air to escape on inspiration without being sucked in), which converts an open pneumothorax to a closed one. Then provide high-flow oxygen and prepare for chest tube insertion.', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000025', 'a1000000-0000-0000-0000-000000000014', 'What is the priority for a multiple-trauma client with suspected spinal injury?', 'MC', 'MEDIUM', 'Immobilize the spine: maintain manual in-line stabilization, use a rigid cervical collar and long backboard with straps, log-roll with at least three people, and avoid twisting the spine. Airway management takes precedence but must preserve C-spine alignment.', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000026', 'a1000000-0000-0000-0000-000000000014', 'What are the cardinal signs of increased intracranial pressure (ICP)?', 'MC', 'MEDIUM', 'Classic triad: headache, vomiting (without nausea), and altered level of consciousness (decreasing GCS). Late signs: Cushing response (hypertension, bradycardia, irregular respirations) and papilledema. Pupils may become unequal.', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000027', 'a1000000-0000-0000-0000-000000000014', 'What nursing interventions reduce intracranial pressure?', 'MC', 'MEDIUM', 'Elevate the head of bed 30-45 degrees, keep the neck in midline to promote venous drainage, maintain normothermia and normocarbia (avoid hyperventilation unless herniating), control pain/seizures, and prevent straining (stool softeners, suctioning gently).', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000028', 'a1000000-0000-0000-0000-000000000014', 'What are the signs of brain herniation?', 'MC', 'HARD', 'Uncal herniation: ipsilateral pupillary dilation (CN III compression), contralateral hemiparesis, and decreasing level of consciousness progressing to posturing and respiratory arrest. It is a fatal emergency requiring immediate osmotherapy or surgery.', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000029', 'a1000000-0000-0000-0000-000000000014', 'What is the immediate nursing care for a chemical burn of the eye?', 'MC', 'MEDIUM', 'Irrigate copiously with normal saline or lukewarm water for at least 15-30 minutes, starting immediately — do not delay for pH testing. Irrigate from the inner canthus outward to avoid washing contaminant into the other eye; remove contact lenses early.', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000030', 'a1000000-0000-0000-0000-000000000014', 'How is burn surface area estimated in adults using the Rule of Nines?', 'MC', 'MEDIUM', 'Rule of Nines (adult): head and each arm 9% each; anterior trunk 18%, posterior trunk 18%; each leg 18% (total lower extremities 36%); perineum 1%. The patient palm equals about 1% body surface area for small/multiple areas.', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000031', 'a1000000-0000-0000-0000-000000000014', 'What is the priority in the first 24 hours of a major burn?', 'MC', 'MEDIUM', 'Airway (inhalation injury, facial burns), then fluid resuscitation with the Parkland formula (4 mL x kg x %TBSA in the first 24 hours: half in first 8 hours from time of burn), pain control, and warming. Monitor urine output (0.5-1 mL/kg/hr in adults).', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000032', 'a1000000-0000-0000-0000-000000000014', 'What is the correct initial first aid for a thermal burn?', 'MC', 'MEDIUM', 'Cool the burn with lukewarm running water for 10-20 minutes (avoid ice, which causes vasoconstriction and further tissue damage), remove constricting items and wet clothing, cover with a clean non-fluffy dressing, and do not break blisters.', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000033', 'a1000000-0000-0000-0000-000000000014', 'What are the priorities for a client with a head injury and suspected increased ICP during transport?', 'MC', 'MEDIUM', 'Maintain airway with cervical spine precautions, keep the head elevated 30 degrees and midline, avoid hypoxia and hypotension (both worsen outcomes), control agitation and pain, and monitor GCS and pupils en route to a trauma center.', false, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000034', 'a1000000-0000-0000-0000-000000000014', 'What is the nursing intervention for a client with a dislocated joint?', 'MC', 'MEDIUM', 'Immobilize the joint in the position found with a splint, apply ice and elevate to reduce swelling, check distal pulses and sensation (neurovascular status with the 6 Ps), provide analgesia, and prepare for reduction by the physician. Never attempt to reduce the joint.', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000035', 'a1000000-0000-0000-0000-000000000014', 'What is the immediate management of a fractured femur?', 'MC', 'MEDIUM', 'Control hemorrhage (a femur fracture can lose 1-1.5 liters of blood), immobilize with a traction splint in the position found, assess for shock, monitor neurovascular status distal to the injury, and prepare for definitive care. Do not attempt to straighten the leg.', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000036', 'a1000000-0000-0000-0000-000000000014', 'Which emergency situation requires the Heimlich maneuver (abdominal thrusts)?', 'MC', 'EASY', 'Foreign-body airway obstruction in a conscious choking victim: 5 abdominal thrusts for adults and children over 1 year, alternating with back blows for infants. If the victim becomes unconscious, begin CPR and check the mouth before ventilations.', true, true, NOW(), NOW()),
('b0000014-0000-0000-0000-000000000037', 'a1000000-0000-0000-0000-000000000014', 'What is the role of the nurse during the recovery phase of a disaster?', 'MC', 'MEDIUM', 'During recovery, nurses restore services, provide psychosocial support (psychological first aid), surveil for communicable diseases, participate in after-action review and data collection, and support rebuilding of community capacity and continuity of care.', false, true, NOW(), NOW());

COMMIT;
